window.GOHUD_SEARCH=window.GOHUD_SEARCH||{};
window.GOHUD_SEARCH["uk"]={"p":["index.html","install.html","ai.html","widgets.html","theming.html"],"n":["Огляд","Встановлення","AI SKILL","Віджети","Оформлення"],"d":[[0,"showcase","Який вигляд це має у грі",0,"Середньовічний і сай-фай пресети — картка персонажа, інвентар і завдання; форми, сітки та картки-запити; кутасті панелі й сенсорне керування. Пресет перемикається одним рядком коду. Середньовіччя — персонаж, інвентар і завдання Середньовіччя — форми, сітки та картки-запити Сай-фай — кутасті панелі й сенсорне керування Усі шість пресетів і як їх перемикати →","",-1],[0,"what","Що він знімає з ваших плечей",0,"Найбільше часу в ігровому інтерфейсі з'їдає не форма кнопки — а все те, що розповзається між пристроями. gohud тримає це розповзання в одному місці. Кожен розмір — це токен Відступи, кути й розміри тексту звуться на ім'я, а не пишуться числами. Змініть тему — і весь екран рушить разом із нею. Видимий розмір ≠ розмір натискання Кнопка закриття виглядає на 36dp, але її область дотику — 48dp. Там, де тісні слоти перекриваються, натискання дістається тому, чий центр ближче. Вирізи й клавіатури Частини HUD сидять усередині безпечної зони, а поле вводу підіймається над віртуальною клавіатурою, коли та з'являється. «Назад» закриває одне Escape і апаратна кнопка «Назад» на Android закривають лише найверхнішу поверхню. Складені одне на одному вікна не зникають разом. Сповіщення не крадуть ввід Натисніть крізь снекбар — і кнопка під ним отримає натискання. Фокус теж не забирається. Іконки запитують на ім'я Віджети знають лише GoIconSet.CLOSE. Замініть набір — і всі малюнки зміняться, не чіпаючи жодного рядка коду. Шість образів, один рядок GoUi.use_preset() міняє тему, скін та іконки разом — заокруглені, зрізані сай-фай чи ковані середньовічні рами. Розбірливість — виміряна Кожна тема перевіряється за WCAG, разом зі станами кнопок і напівпрозорими панелями HUD над чисто білим і чисто чорним тлом. Усе працює й без увімкнення плагіна. Увімкнення додає автозавантаження GoRuntime, яке стежить за розміром вікна, масштабом dp і висотою клавіатури, а також параметри проєкту для ресурсу налаштувань і пресету — це зручності, а не вимоги.","",-1],[0,"install","Встановлення gohud",0,"Два шляхи. Доручіть ШІ-агенту або покладіть теку у свій проєкт — більше нічого налаштовувати. Встановлення","",-1],[0,"start","Швидкий старт",0,"П'ять рядків виводять екран з темою. Повний шлях — на сторінці встановлення. Швидкий старт","",-1],[0,"presets","Змініть образ — кольори і форму",0,"Тема може перестилізувати лише те, що малює рушій. Заокруглені кути — єдині, які має StyleBoxFlat, а стик, швидкі слоти й коуч-мітка малюються кодом, тож самою лише темою їхню форму не змінити ніколи. Тому gohud постачає пресети: тема, скін і набір іконок, вибрані як одне ціле. Пресет Образ default_dark Первісний gohud — заокруглені кути, м'який синій акцент default_light Ті самі форми на світлій палітрі scifi_dark Зрізані кути, блакитні неонові краї та сяйво, шестикутний стик, прицільні дужки scifi_light Ті самі кутасті форми в яскравій «кресленицькій» палітрі medieval_dark Темне залізо й шкіра, рами під старе золото, заклепки, гравійовані іконки, заголовки шрифтом Cinzel medieval_light Пергамент, чорнило й бронза з тими самими кованими рамами default_dark — заокруглені кути, м'який синій акцент default_light — ті самі форми, світла палітра scifi_dark — зрізані кути, блакитний неон scifi_light — ті самі кутасті форми, «кресленицька» палітра Ці чотири — той самий екран галереї. Не різниться жодного рядка коду — лише назва пресету. Кути кнопок, форми перемикачів, рядки списків і рамки полів вводу рухаються разом.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # тема, скін та іконки разом",-1],[0,"medieval-collection","Середньовічна колекція",1,"medieval_dark поєднує залізо та шкіру зі старим золотом; medieval_light бере пергамент і чорнило. Рами меню несуть заклепку й невелику кутову оздобу, тоді як завжди видимий HUD лишається стриманим; 16 гравійованих іконок перемальовують назви предметів, а вбудований шрифт Cinzel вживається лише в заголовках і підзаголовках. medieval_dark — залізо та шкіра medieval_light — пергамент і чорнило Обидва знімки — це examples/medieval/medieval.tscn, зібраний зі стандартних віджетів. Середньовічний посібник і як зробити власне королівство →","",4],[0,"the-same-screen-on-a-phone-and-on-a-desktop","Той самий екран на телефоні й на комп'ютері",1,"Знімки галереї — це телефон у портреті. Нижче — той самий код на 1280×800: вміст спиняється на зручній для читання ширині (480dp) і центрується, а HUD лишається по кутках. Форма обходить плаваючі частини HUD, але не рухається, якщо вже стоїть осторонь них: штовхати її попри це означало б зсунути вміст із центру на широкому екрані. default_dark · 1280×800 scifi_dark · 1280×800","",4],[0,"the-same-sheet-a-different-look","Той самий аркуш, інший образ",1,"Стандартний — заокруглена картка, липкий рядок пошуку та підвал Сай-фай — акцентний край згори, зрізані кути, сяйво Виберіть один у Параметрах проєкту → gohud → Theme → Preset або задайте GoConfig.preset. Явно заповнені theme, skin чи icons переважають над пресетом, тож можна взяти пресет і перевизначити лише одне з них. Нова тема — це один файл JSON. new_theme.py kingdom --from medieval_dark пише палітру, у якій розписано кожне успадковане значення; make_theme.py kingdom збирає тему, її графіку для контролів і регулятори скіна, і пресет з'являється у списку вибору. Кожен параметр і регулятор →","",4],[0,"skin","Скіни — там, куди темі не дістатися",0,"Скіну належать стик, лицьові боки швидких слотів, кільце коуч-мітки, чипи, скелетони, сповіщення, роздільники та заголовки секцій. Успадкуйте його й перевизначте лише те, що хочете змінити. Клас Які форми вміє GoStyleBoxCut Кути, зрізані по діагоналі (фаска), один потовщений акцентний край, зовнішнє сяйво GoStyleBoxBracket Лише кутові позначки, без обрамлення вмісту GoStyleBoxMedieval Кована рама із заклепками, кутовим гравіюванням, фаскою-відблиском і зернистістю матеріалу Усі три серіалізуються в ресурс Theme — саме це й дозволяє темі міняти форму, а не лише колір. GoSkinSciFi і GoSkinMedieval — вбудовані підкласи. GoStyle.box() завжди повертає StyleBoxFlat, бо код, який його викликає, отримує результат і правит bg_color чи corner_radius. Коли власна форма мусить вціліти, користуйтеся GoStyle.surface().","class_name MySkin extends GoSkin func slot_box(accent: Color, lit: bool) -> StyleBox: var box := GoStyleBoxCut.new() box.bg_color = accent box.cut = 6.0 box.edge_color = accent return box",-1],[0,"widgets","Віджети",0,"Усі складники в одній таблиці. Кожен докладно → Клас Основа Що робить GoSurface Control Оболонка плаваючої картки — розміщення по центру, знизу чи біля прив'язки, липкі заголовок і підвал, тіло з прокруткою, зміна розміру перетягуванням GoSheet CanvasLayer Сторінки, що підіймаються знизу, на власному шарі — тож сидять над HUD GoDialogs Node Підтвердження та сповіщення, на які ви робите await; destructive — для незворотних дій GoForm MarginContainer Форми з обмеженою шириною, що обходять віртуальну клавіатуру, а з avoid_hud — і HUD GoScroll ScrollContainer Сенсорна прокрутка; смуга прокрутки ховається в поля картки GoNotice PanelContainer Снекбар, що не бере ні вводу, ні фокуса GoPromptCard PanelContainer Запитання, яке не блокує гру GoCoachMark Control Навчальний тур, що вказує на справжні контроли; натискання на ціль веде далі GoHudAnchor Control Прикріплює частини HUD до одного з дев'яти місць у безпечній зоні GoBar Control Смуги здоров'я, мани та досвіду з плавними змінами GoSlot Button Швидкий слот — іконка, кількість, відкат і гаряча клавіша на одному лицьовому боці GoJoystick Control Віртуальний стик у фіксованому, слідуючому чи відносному режимі GoIconButton Button Виглядає малою, натискається великою GoStyle static Кнопки, рядки списків, поля вводу, чипи, таблиці, вкладки та інше — зроблені одним послідовним способом","",-1],[0,"ai","AI SKILL",0,"gohud має ШІ-навичку: увесь API, готові до запуску шаблони та запуск попереднього перегляду. Вставте один блок у свого агента — він встановить gohud і знатиме, як ним користуватися. AI SKILL","",-1],[0,"readable","Розбірливість вимірюють, а не оцінюють на око",0,"«Гарно» — справа смаку; «розбірливо» можна виміряти. Блідий сірий текст чудово виглядає на доброму моніторі й зникає на телефоні серед білого дня — вибір на око рано чи пізно це гарантує. Кожна пара кольорів і напис кожного стану кнопки над панеллю, на якій він лежить, вимірюються за WCAG в усіх шести темах. Напівпрозорі кольори спершу накладаються на своє справжнє тло — виміряні напряму, вони показують кращий коефіцієнт, ніж видно на екрані. Тому кольори тексту виводяться, а не вибираються: конструктор бере запис палітри за відправну точку й піднімає його світлість, доки той не перевищить поріг на кожній поверхні, куди може лягти. Змініть палітру — і контраст рушить услід. Правила й пастки за ними → Перевірки, релізи й цей сайт Одна точка входу запускає всі перевірки; кожна частина бачить те, чого не бачать інші. Перевірка Що ловить run_tests.sh на чотирьох розмірах екрана Поведінку та компонування віджетів, позиції в RTL, фокус із клавіатури, контраст скіна під час виконання, кожен пресет new_project_check.sh Приховані залежності від проєкту-господаря; з --zip — реліз у тому вигляді, в якому він постачається, з --export — вебзбірку check_contrast.py Контраст за WCAG у кожному файлі теми, разом зі станами кнопок і напівпрозорими панелями check_generated.py · check_scaffold.sh Що згенеровані теми відповідають своїм палітрам; що одноразова тема збирається й проходить перевірку контрасту check_package.py Підняття версії, перенесення записів журналу змін і вміст ZIP — у тимчасових копіях check_site.py Посилання, якорі, мову сторінок, глосарій і таблиці регуляторів цього сайту Останній записаний прогін — 2026-09-13, Godot 4.7.2, macOS, рендерер Compatibility. 438 із 438 перевірок на 390×844, 844×390, 768×1024 і 1280×800 у порожньому проєкті; знову 438 із 438 з автозавантаженням GoRuntime; вебекспорт; жодного провалу за контрастом у всіх шести темах. Godot 4.6 та фізичні пристрої на Android чи iOS у цей прогін не входили.","python3 addons/gohud/tools/check_contrast.py bash addons/gohud/tools/check_all.sh",-1],[0,"release-versions","Версії релізів",1,"Успішний прогін оновлює plugin.cfg, GoUi.VERSION і CHANGELOG.md разом, переносячи нотатки з розділу Unreleased у датований запис. Невдалий прогін не змінює нічого, а наявний ZIP ніколи не перезаписується. До ZIP не потрапляють ні цей сайт, ні тести, ні інструменти.","bash addons/gohud/tools/package.sh # 1.0.1 → 1.0.2 · builds/1.0.2/gohud-1.0.2.zip bash addons/gohud/tools/package.sh --increase-minor-version # 1.0.1 → 1.1.0",11],[0,"this-site","Цей сайт",1,"Сторінки — це звичайний HTML у www/: англійська в корені, корейська в ko/. Робочий процес GitHub Actions публікує цю теку як корінь сайту.","python3 addons/gohud/tools/make_site.py # глосарій і таблиці регуляторів скіна, згенеровані з коду python3 addons/gohud/tools/check_site.py # посилання, якорі, мова, глосарій, згенеровані таблиці bash addons/gohud/tools/site_shots.sh /tmp/shots # знімки кожної сторінки на комп'ютері й на телефоні",11],[1,"ai-first","Найшвидший шлях — доручіть встановлення ШІ-агенту",0,"Один блок тексту, вставлений у Claude Code, Codex, Cursor чи Gemini CLI, встановить і навичку, і доповнення, а тоді пояснить вам gohud. На цьому шляху ніщо нижче цієї картки не потрібне. Відкрити сторінку AI SKILL →","",-1],[1,"install","Встановлення",0,"Покладіть теку доповнення у свій проєкт. Більше нічого налаштовувати не треба.","",-1],[1,"from-the-asset-store-or-a-release-zip","З Asset Store або ZIP-архіву релізу",1,"Розпакуйте в корінь проєкту так, щоб вийшло res://addons/gohud/. Це все. За бажання увімкніть Проєкт → Параметри проєкту → Плагіни → gohud.","",15],[1,"as-a-git-submodule","Як підмодуль git",1,"Корінь репозиторію і є текою доповнення, тож він лягає рівно туди, де його чекає Godot. Редагуйте на місці, комітьте й пуште всередині addons/gohud, а тоді закомітьте вказівник підмодуля у своїй грі. Потрібен Godot 4.6 або новіший. gohud користується API, що з'явилися в 4.5 (DPITexture, FoldableContainer, властивості доступності), тож на будь-чому старішому він падає ще на розборі. 4.6 — підтримувана нижня межа, записана в GoUi.MIN_ENGINE.","git submodule add https://github.com/thruthesky/gohud.git addons/gohud git submodule update --init git -C addons/gohud checkout v1.0.0 # необов'язково: закріпити тег або коміт",15],[1,"start","Швидкий старт",0,"Кожен віджет — це .new() та add_child(): жодних файлів сцен, жодного автозавантаження.","",-1],[1,"pick-a-look-before-building-ui-optional","Виберіть образ до того, як будувати UI (необов'язково)",1,"","GoUi.use_preset(GoThemePresets.SCIFI_DARK) # якщо пропустити, буде default_dark",18],[1,"a-confirmation-you-await","Підтвердження, на яке ви робите await",1,"Передайте destructive = true (останній аргумент) — і кнопка підтвердження намалюється як залита кнопка небезпеки.","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Видалити збереження\", \"Цю дію не можна скасувати.\"): delete_save()",18],[1,"a-bottom-sheet-with-a-sticky-search-field-and-fo","Нижній аркуш із липким полем пошуку та підвалом",1,"Чому липкі рядки відокремлені від тіла з прокруткою. Покладіть підтвердження та скасування в body — і довгий список виштовхне їх за екран. footer() видно завжди.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Інвентар\") sheet.toolbar().add_child(GoStyle.line_edit(\"Пошук…\")) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, _use.bind(item), Color.TRANSPARENT, item.description, false)) sheet.footer().add_child(GoStyle.button(\"Закрити\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",18],[1,"a-hud-corner","Куток HUD",1,"","var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.landscape_spot = GoHudAnchor.Spot.TOP_RIGHT add_child(corner) var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) corner.add_child(hp) hp.set_values(320, 500)",18],[1,"content-that-keeps-clear-of-the-hud","Вміст, що тримається осторонь HUD",1,"Кожен прямокутник обходиться в тому напрямку, який коштує найменше площі — униз на телефоні в портреті, убік у ландшафті. Як HUD обходить сам себе →","form.avoid_hud = true # обходити кожен видимий GoHudAnchor joystick_anchor.reserve_space = false # …окрім тих, що з'являються лише під пальцем notice_anchor.avoid_peers = true # снекбар осідає під нерухомим HUD, а не накриває його",18],[1,"examples","Приклади, які можна запустити",0,"Три способи побачити gohud, не написавши ані рядка, — жодному не потрібні ні сервер, ні автозавантаження. Приклад Як відкрити Що показує Галерея examples/gallery/gallery.tscn · F6 Кожен віджет, список вибору для всіх встановлених пресетів і повний набір іконок Середньовіччя examples/medieval/medieval.tscn · F6 Картка персонажа, торба та журнал завдань; кнопки перемикають залізо й пергамент і відкривають подробиці предметів Застосунок демо cd examples/demo && godot Домашній екран, що відкриває галерею, екскурсію з 15 розділів, вітринний екран і середньовічний образ, із живими віджетами й однією карткою на клас Застосунок демо не потребує налаштування: якщо бракує посилання на доповнення чи кешу імпорту, він про це скаже, полагодить теку й перевідкриє себе. Його домашній екран відкриває кожен приклад у тому самому вікні — натисніть 1–4 чи клацніть рядок, а смуга вгорі поверне вас назад. В екскурсії C вмикає кінорежим, F11 — повний екран, Пробіл ставить на паузу (або програє поточний віджет у режимі дослідження), стрілки міняють розділи, а Escape повертає на початок. Користуєтеся AI-агентом для написання коду? Відкрийте всі три однією командою →","cd examples/demo && godot # домашній екран; при першому запуску створює посилання й імпортує bash examples/demo/run.sh # той самий застосунок, із кореня доповнення bash examples/demo/run.sh -- --open=gallery # пропустити домашній екран bash examples/demo/run.sh -- --explore=surfaces # відкрити одразу на одному розділі екскурсії bash examples/demo/run.sh --record /tmp/gohud-demo.avi # запис екскурсії 1080p / 60 к/с",-1],[2,"copy","Вставте це у свій ШІ-агент",0,"Відкрийте проєкт Godot в агенті, вставте блок і надішліть. Він встановить навичку та доповнення, а тоді розповість, що вміє gohud. Блок навмисно написано англійською — саме її кожен агент читає найточніше. Свої запитання ставте будь-якою мовою: навичка відповідає тією, якою ви пишете.","Install gohud for this Godot 4.6+ project, then use it for all game UI (menus, HUD bars, quick slots, dialogs, bottom sheets, forms, themes). 1. Install the gohud AI skill. Claude Code: claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud Any other agent (Codex, Cursor, Gemini CLI, ...): git clone --depth 1 https://github.com/thruthesky/gohud.git /tmp/gohud Copy /tmp/gohud/skills/gohud into whichever of these folders this agent reads: ~/.claude/skills/gohud, .claude/skills/gohud, .agents/skills/gohud. 2. Install the add-on itself, if addons/gohud/plugin.cfg is missing here. In a git repository: git submodule add https://github.com/thruthesky/gohud.git addons/gohud Otherwise copy the clone to addons/gohud without its .git folder. Then run: godot --headless --path . --import 3. Restart yourself so the skill loads, then tell me what gohud can do and how to preview it. Docs: https://thruthesky.github.io/gohud/",-1],[2,"agents","Де кожен агент тримає навички",0,"Волієте встановити вручну? Покладіть теку skills/gohud туди, звідки читає ваш агент. Перемагає перша наявна. Агент Куди класти теку Вигляд команд Claude Code — плагін claude plugin install gohud@gohud /gohud:preview · /gohud:features Claude Code — лише навичка ~/.claude/skills/gohud /gohud preview · /gohud features Claude Code — лише цей проєкт .claude/skills/gohud /gohud preview Codex · Cursor · Gemini CLI — інші .agents/skills/gohud —","",-1],[2,"commands","Команди, які ви отримаєте",0,"","",-1],[2,"gohud-preview-the-widget-gallery","/gohud:preview — галерея віджетів",1,"Відкриває галерею: кожен віджет, вибір із усіх шести пресетів і повний набір іконок. Наберіть її всередині свого проєкту Godot — і використається ваш addons/gohud; без нього береться копія, вкладена в плагін, або свіжий клон. Вона працює в одноразовому пісочничному проєкті, тож ваші автозавантаження та кеш імпорту лишаються недоторканими, а вікно стоїть відкритим, доки ви його не закриєте.","",27],[2,"gohud-preview-demo-the-15-chapter-guided-tour","/gohud:preview demo — екскурсія з 15 розділів",1,"Відкриває демо на початковому екрані. Запустити демо програє екскурсію справжнім вводом; Дослідити віджети дає спробувати один віджет вручну. Клавіші, перелічені в розділі Приклади, працюють і тут.","",27],[2,"many-other-commands","Багато інших команд",1,"Команда Що робить /gohud:preview medieval Картка персонажа, торба та журнал завдань у середньовічних пресетах /gohud:preview demo --explore hud Демо, відкрите одразу на одному розділі — hud buttons inputs selection lists data states surfaces prompt touch coach scrolling forms anchors theming /gohud:preview gallery --preset scifi_dark Галерея в одному пресеті; додайте --phone для вікна телефона 390×844 або --size 1920x1080 для будь-якого розміру /gohud:preview res://ui/main_menu.tscn Сцена вашого власного проєкту, запущена всередині нього /gohud:preview list Усі цілі, ідентифікатори пресетів і ключі розділів демо /gohud:preview gallery --check Безвіконна димова перевірка — падає на помилках скриптів /gohud:features Кожна можливість, згрупована, по одному рядку коду на кожну /gohud:features hud Одна ділянка вглиб — surfaces hud style theming icons i18n accessibility config Команди попереднього перегляду потребують Godot 4.6 або новішого у PATH.","",27],[2,"ask","Або просто попросіть",0,"Або просто попросіть. Уміння навчає агента всього API gohud, тож звичайні прохання теж працюють — «Зроби меню паузи на gohud». Якщо встановити його як звичайне вміння в ~/.claude/skills/gohud, команди пишуться через пробіл: /gohud preview demo, /gohud features. Для попереднього перегляду потрібен Godot 4.6 або новіший у PATH, або передайте --godot /path/to/godot.","",-1],[3,"surfaces","Плаваючі вікна",0,"","",-1],[3,"gosurface-the-shell","GoSurface — оболонка",1,"Спливні вікна, аркуші та випадні списки — усі користуються цим одним. Він дає раду безпечній зоні, віртуальній клавіатурі, липким заголовку та підвалу, тілу з прокруткою, тому, яке вікно найверхніше, поверненню фокуса, володінню кнопкою «Назад» і зміні розміру перетягуванням. Розміщення Має вигляд Для чого CENTER Картка посередині Підтвердження, налаштування BOTTOM Аркуш, що підіймається знизу Списки, сторінки керування ANCHOR Картка, приколена біля контрола Випадні списки, контекстні меню Він не прибирає себе сам. Відреагувати на close_requested — сховати чи звільнити — має екран-власник, бо оболонка не може знати, чому вона закривається (зберегти й закрити чи відкинути).","",32],[3,"gosheet-a-page-from-the-bottom","GoSheet — сторінка знизу",1,"Він володіє власним CanvasLayer, тож надійно сидить над HUD. open() очищає тіло й вимикає кнопку «Назад» і липкі рядки — мертва кнопка на екрані, звідки нікуди повертатися, читається як зламана.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Інвентар\") sheet.toolbar().add_child(GoStyle.line_edit(\"Пошук…\")) sheet.toolbar().visible = true sheet.footer().add_child(GoStyle.button(\"Закрити\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",32],[3,"godialogs-confirmations-you-await","GoDialogs — підтвердження, на які ви робите await",1,"confirm(title, body, ok_text, cancel_text, extra, args, destructive) — усе після тексту необов'язкове, а alert() працює так само, але з однією кнопкою. Задайте destructive для того, чого не можна скасувати: кнопка підтвердження стає залитою кнопкою GoStyle.Tone.DANGER_SOLID. У світлій темі підфарбований напис небезпеки мусить темніти, доки не читатиметься як чорний текст; залита кнопка ж лишає білий текст на червоному. Тон накладається заново при кожному виклику, бо одне вікно використовується повторно, а другий confirm(), поки відкрите перше, одразу повертає false. confirm_key() приймає ключі перекладу. Розкладка кнопок. action_layout типово дорівнює VERTICAL (безпечно для довгих перекладів), HORIZONTAL дає один рядок із половиною ширини на кожну, а AUTO бере один рядок лише тоді, коли обидва написи вміщаються в половину картки одним рядком, інакше складає їх стовпчиком. action_gap — це проміжок між кнопками, а body_gap — проміжок над ними; зробіть його ширшим за проміжок між кнопками, щоб запитання й вибір читалися як дві частини. Для одного-єдиного діалогу викличте set_next_action_layout() перед його відкриттям. Рядок будується при першому відкритті діалогу, тож GoDialogs в автозавантаженні не додає нічого на старті.","if await dialogs.confirm(\"Видалити збереження\", \"Цю дію не можна скасувати.\"): delete_save()",32],[3,"goform-a-width-capped-form","GoForm — форма з обмеженою шириною",1,"Вона гарантує, що написи-нащадки переносяться. Без цього одне довге речення розтягується в єдиний рядок, чия мінімальна ширина перевищує екран, і краї обрізаються — ви навіть не розберете, на якому екрані перебуваєте. Вмикати перенесення вручну в кожній сцені забувають щоразу.","",32],[3,"goscroll-touch-scrolling","GoScroll — сенсорна прокрутка",1,"Кладіть усередину одну річ. Заголовки й ряди кнопок належать назовні — довгий список не повинен виштовхувати їх за екран. use_panel_edge() переносить смугу прокрутки в наявні поля картки, а вміст зберігає свій відступ.","",32],[3,"messages","Як сказати щось гравцеві",0,"","",-1],[3,"gonotice-snackbar","GoNotice — снекбар",1,"Він ніколи не перехоплює ввід. Сповіщення читають, а не натискають. Воно не бере фокуса, не блокує ігровий ввід, і кнопка під ним усе одно натискається. Коли потрібне підтвердження, беріть GoDialogs; коли потрібен вибір — GoPromptCard.","",38],[3,"gopromptcard-a-question-that-does-not-block","GoPromptCard — запитання, яке не блокує",1,"Плаває збоку без затемнення. Гра йде далі.","",38],[3,"gocoachmark-guided-tour","GoCoachMark — навчальний тур",1,"Вказує на справжні контроли по одному. Ввід бере лише картка, тож натискання на сам підсвічений контрол веде тур далі — «натисніть тут» стає дією, а не реченням. title і body можуть бути ключами перекладу або звичайним текстом. Крок, чия ціль зникла, пропускається.","tour.start([ {\"target\": bag_button, \"title\": \"Торба\", \"body\": \"Усе, що ви підбираєте, потрапляє сюди.\"}, {\"target\": map_button, \"title\": \"Карта\", \"body\": \"Натисніть, щоб відкрити повну карту.\"}, ])",38],[3,"hud","HUD",0,"","",-1],[3,"the-small-things-decide-whether-it-looks-good","Дрібниці вирішують, чи має воно гарний вигляд",1,"Вилизуйте великі панелі скільки завгодно — око завжди чіпляється за щось маленьке: розірване надвоє слово, зрізане сяйво, затиснутий слот. Чотири такі речі показали 13 вересня 2026 року, і полагоджено їх було у віджетах і темах, а не на екрані демо, тож той самий результат дістається кожному екрану. Що виявилося Причина Полагоджено Напис Done на коуч-мітці став Don/e Кнопка з увімкненим перенесенням віднімає ширину свого тексту від свого мінімуму — стисніть її, і вона розірветься всередині слова GoStyle.fit_words(): одне слово не переноситься ніколи; кілька слів переносяться, але найдовше слово вміщається завжди — рішення ухвалюється за показаним текстом, а не за ключем перекладу, і накладається наново формою, коли змінюється мова У кнопки на всю ширину сяйво зрізалося по вертикалі зліва Контейнер прокрутки обрізає на своєму краю без винятків. Уцілів лише правий бік — завдяки жолобу для смуги прокрутки GoScroll позичає поле в батька, щоб відсунути свій край на 12dp назовні, і повертає його всередині — вміст лишається на місці Час, іконка й кількість склалися в слоті стовпчиком Три рядки всередині 48dp Іконка велика по центру, гаряча клавіша вгорі зліва, кількість бейджем унизу справа, час, що лишився, — бейджем над іконкою; панелі бейджів приходять зі скінового badge_box() Плаский випадний список без видимого вибору Наведення на пункт брало панель кнопки, а позначки-перемикачі були блідими типовими від рушія Окрема панель наведення (м'яке акцентне підфарбування), та сама графіка перемикачів, що й у прапорців, висота пункту під дотик Випадний список — панель наведення й позначка вибору Слоти — кутові бейджі й час, що лишився (сай-фай) Дайте кнопкам лише з іконкою опис через GoStyle.icon_button(icon, action, -1, tooltip_key) — і підказка для тих, хто з мишею, і назва для зчитувачів екрана беруться з цього одного значення. gohud малює підказку сам: типова від рушія розбиває текст по одному символу на рядок, коли її обчислення ширини йде не так (виміряно на ширині 1dp). Картка коуч-мітки тримається осторонь нерухомого У ландшафті картку раніше відсилало на самий верхній або нижній край — рівно туди, де живуть заголовки й частини HUD; у демо вона сіла на → × у заголовку. Тепер вона лишається на рівні своєї цілі, обходить будь-який GoHudAnchor, що резервує місце, і приймає інші перешкоди через keep_clear. Вона рухається на найкоротшу відстань, яка обходить перешкоду, не накриваючи ціль, і лишається на місці, коли екран замалий, щоб обійти все, — перекритися краще, ніж зникнути. Її глибина — щоб читалася як над сторінкою — береться з регуляторів скіна (float_shadow_size, float_shadow_lift, float_shadow_alpha; скіни зі зрізаними кутами беруть float_glow_size).","tour.keep_clear = [header_bar, toolbar] # нерухомі елементи, що не є прив'язками",42],[3,"screens-with-a-mouse-and-a-keyboard","Екрани з мишею та клавіатурою",1,"У пальця немає стану наведення. Будуйте лише під мобільні — і два стани, які бувають тільки на комп'ютері, лишаться неперевіреними; один із них таки був зламаний: у gohud кільце фокуса було невидиме на головній кнопці. Панель мала колір акценту, і кільце теж: 1,00:1, той самий колір, намальований сам на собі. Рухаючись клавіатурою, годі було зрозуміти, де ти. Згори вниз: звичайний · наведення · фокус. Заліті кнопки дістають кільце, що контрастує з їхньою панеллю. Заліті кнопки (GoPrimaryButton, GoDangerSolidButton) беруть кільце, яке контрастує з їхньою власною панеллю — темне в темній темі, біле у світлій, темна прицільна дужка в сай-фай. Перевіряльник контрасту вимірює кільце фокуса проти панелі, на якій воно лежить, тож правило переживає зміну палітри (WCAG 2.4.11 вимагає 3:1 для індикаторів фокуса).","",42],[3,"hud-widgets","Віджети HUD",0,"","",-1],[3,"gohudanchor-nine-spots","GoHudAnchor — дев'ять місць",1,"Шанує безпечну зону та крайові поля. Дайте йому landscape_spot — і він переїде в ландшафті: контроли, що в портреті сидять унизу по центру, можуть перейти вниз праворуч. Навіщо це існує. Прописані вручну для кожної частини HUD прив'язки та зсуви розповзаються: смуга здоров'я опиняється під вирізом камери на пристрої з «чубчиком», а кнопка керування сідає на жестову смугу в ландшафті. Уся ця арифметика живе в одному місці. Як не пускати вміст під HUD Коли екран із прокруткою ділить дисплей із HUD, вміст з'їжджає під нього, і два набори тексту накладаються, доки жодного не можна прочитати. У цьому доповненні таке траплялося двічі: підказка поля вводу вичавлювалася між швидкими слотами, а повзунок перемикача в налаштуваннях сідав на смугу здоров'я. Кожен прямокутник обходиться в тому напрямку, який коштує найменше площі. Смуга вгорі справа обходиться вниз на телефоні в портреті (13% висоти) і вбік у ландшафті (21% ширини) — обходити її по вертикалі в ландшафті коштувало б 27% екрана. Уже віддану площу віднімають, перш ніж міряти наступний прямокутник. Частини HUD стикаються й між собою Дев'ять місць ділять екран; вони не гарантують, що частини розминуться. Широкий снекбар угорі по центру сів просто на смугу здоров'я вгорі справа й затулив значення — годі було прочитати, скільки здоров'я лишилося. Він відступає лише по вертикалі — відступ убік означав би, що центрований снекбар щоразу з'являється в іншому місці. І він обходить лише ті частини, які не відступають самі: якщо поступляться обидві, вони мінятимуться місцями довіку.","form.avoid_hud = true # обходити кожен видимий GoHudAnchor joystick_anchor.reserve_space = false # …окрім тих, що з'являються лише під пальцем notice_anchor.avoid_peers = true # осідає під нерухомим HUD notice_anchor.reserve_space = false # і не штовхає сторінку, поки висить",45],[3,"gobar-health-mana-experience","GoBar — здоров'я, мана, досвід",1,"Зміни плавно йдуть за 0,18 с — смуга здоров'я, що стрибає, не каже, наскільки сильно вас вдарили. reduce_motion робить зміну миттєвою. Великі числа скорочуються до 12.3k, щоб ширина смуги не сіпалася, коли цифри приходять і йдуть.","var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) # токен лише для заливки hp.set_values(320, 500) # \"320 / 500\"",45],[3,"goslot-one-quick-slot","GoSlot — один швидкий слот",1,"Іконка, кількість, відкат і гаряча клавіша на одному лицьовому боці. Якщо чіпляти бейджі на маленьке коло, кожен слот виходить іншої ширини, і ряд хитається. Видимий розмір і розмір дотику різні. У щільно складених слотів області дотику в 48dp перекриваються; перекриття дістається тому слоту, чий центр ближче — розкажіть їм одне про одного через touch_peers. keyboard_focus типово вимкнено, щоб ряд із восьми слотів не стояв у порядку Tab між користувачем клавіатури й кожним контролом налаштувань. Вмикайте його, коли клавіатура чи геймпад — єдиний спосіб вводу.","",45],[3,"gojoystick-virtual-stick","GoJoystick — віртуальний стик",1,"Режим Поведінка FIXED Завжди на тому самому місці — легко знайти, не дивлячись FOLLOW З'являється там, де ліг великий палець RELATIVE Після появи далі йде за пальцем — зручно для довгого руху Vector2 із сигналу moved має довжину 0–1, тож його можна одразу множити на швидкість; він не залежить ні від розміру екрана, ні від DPI.","",45],[3,"goiconbutton-looks-small-presses-large","GoIconButton — виглядає малою, натискається великою",1,"Безпечно лише доти, доки сусіди ігнорують ввід. Якщо розширена область накриє сусідню кнопку, та перестане відповідати. Іконковим кнопкам, що стоять поруч, потрібен touch_peers.","",45],[3,"factory","GoStyle — одне місце, де все виготовляється",0,"Викличте Button.new() напряму — і поля, висота та перенесення трохи розповзуться від екрана до екрана. Це розповзання невидиме на рев'ю коду й очевидне на знімку. Група Функції Структура column row wrap_row padding spacer divider responsive_grid aspect foldable Текст label label_key line section typography Кнопки button button_key icon_button list_button list_row apply_icon style_choice_card style_chip_button style_chip_label Ввід line_edit textarea toggle checkbox slider picker select dropdown radio_group segmented choice_grid Показ card chip hud_panel chip_panel avatar skeleton alert table tabs breadcrumb progress empty_state Частини поверхонь surface box floating disc face_padding Помічники form fit_words natural_width tooltip_node card_body let_input_through box() завжди повертає StyleBoxFlat, бо той, хто викликає, отримує його й правит bg_color чи corner_radius. Коли власна форма мусить вціліти, беріть surface().","",-1],[3,"list-rows-with-a-description","Рядки списку з описом",1,"Рядок із другим рядком тексту дістає однакові верхнє й нижнє поля, просторіші за однорядковий, а пара «назва / опис» лишається вирівняною по вертикалі поряд з іконкою — навіть тоді, коли контейнер розтягує рядок вище, і після того, як опис перенісся на кілька рядків. Увесь рядок лишається однією ціллю дотику. Дворядкові рядки, слоти та смуги в середньовічному прикладі — ті самі виклики фабрики під medieval_light.","GoStyle.list_button(GoIconSet.SWORD, \"Вартовий клятви\", _inspect, Color.TRANSPARENT, \"Довгий меч / Атака 42\", false)",51],[3,"flowing-rows","Рядки з перенесенням",1,"Кладіть контроли в wrap_row за їхньою природною шириною. Якщо лишити перенесення увімкненим, мінімальна ширина кнопки падає майже до нуля, і рядок міряє за нею свою комірку — напис стискається до одного символу на рядок. Фабрика робить це замість вас.","",51],[3,"never-leave-an-empty-list-empty","Ніколи не лишайте порожній список порожнім",1,"Порожній екран люди читають як зламаний.","page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"Тут поки що порожньо\"))",51],[3,"hooks","Гуки для підкласів",0,"Кожне місце, де конструюється дочірній віджет, проходить через метод, який можна перевизначити, тож проєкт, що успадковує типи gohud, може отримати власні підкласи всередині віджетів, не копіюючи коду. Гук Віджет Типово _make_scroll() GoCoachMark, GoSurface GoScroll.new() _make_close_button() GoPromptCard, GoSurface GoIconButton.new() _make_surface() GoSheet, GoDialogs GoSurface.new() _should_pause() GoCoachMark Ховає картку, поки відкрите модальне вікно","",-1],[4,"layers","Три шари",0,"Пресет зв'язує всі три. Поля, які ви лишите порожніми, повертаються до типових значень. Шар Вирішує Як його змінити Theme Кольори, розміри, масштаб тексту й форму всього, що малює рушій — панелі кнопок, поля вводу, вкладки, графіку перемикачів Напишіть .tres або згенеруйте його через tools/make_theme.py GoSkin Форму всього, що малює код — стик, лицьові боки швидких слотів, кільце коуч-мітки, чипи, скелетони, роздільники, заголовки секцій Успадкуйте його й перевизначте лише ті методи, які вам потрібні GoIconSet Іконки на ім'я — 84 стандартні малюнки або 16 гравійованих із середньовічного набору поверх них. Пакет текстур чи шрифт іконок; код виклику однаковий в обох випадках Подайте набір або перевизначте лише кілька імен Чому самої лише теми замало. Заокруглений — єдиний кут, який має StyleBoxFlat: поставте радіус у нуль — і отримаєте прямий кут; проміжного нічого немає. Зрізані по діагоналі кути, один потовщений край, зовнішнє сяйво — рушій не малює нічого з цього. А стик і коуч-мітка малюються в _draw(), куди темі не дістатися взагалі.","",-1],[4,"pick","Як вибрати",0,"Цей один рядок міняє тему, скін та іконки. З редактора скористайтеся Параметрами проєкту → Gohud → Theme → Preset; із ресурсу налаштувань — GoConfig.preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK)",-1],[4,"keeping-one-field-your-own","Лишити одне поле своїм",1,"Явно задані theme, skin чи icons переважають над пресетом.","GoUi.use_preset(GoThemePresets.SCIFI_DARK) GoUi.config.icons = my_icons # ваші іконки, решта — від пресету",57],[4,"the-six-built-in-presets","Шість вбудованих пресетів",1,"Пресет Панелі Скін · іконки default_dark · default_light Заокруглені панелі StyleBoxFlat на градуйованій шкалі тіней; головні кнопки підіймаються й осідають при натисканні GoSkin · 84 стандартні іконки scifi_dark · scifi_light Зрізані панелі GoStyleBoxCut із неоновим краєм і сяйвом; позначки фокуса GoStyleBoxBracket GoSkinSciFi — шестикутний стик · стандартні іконки medieval_dark · medieval_light Ковані рами GoStyleBoxMedieval — залізо та шкіра або пергамент — із заклепками й кутовими оздобами в меню GoSkinMedieval · 16 гравійованих іконок поверх стандартних","",57],[4,"medieval","Середньовіччя: залізо, шкіра й пергамент",0,"medieval_dark поєднує темне залізо та шкіру зі старим золотом. medieval_light бере пергамент і чорнило. Обидва використовують GoSkinMedieval, наявні віджети та 16 оригінальних іконок із гравіюванням; іконки навігації повертаються до первісного набору. Виберіть пресет, перш ніж створювати свій інтерфейс. Явні перевизначення GoConfig.theme, skin чи icons і далі мають перевагу. Відкрийте res://addons/gohud/examples/medieval/medieval.tscn і натисніть F6, щоб побачити робочі картку персонажа, торбу та журнал завдань. Її кнопки перемикають варіанти й відкривають подробиці предметів. Залізо та шкіра Пергамент і чорнило Рами меню мають заклепку й невелику кутову оздобу; завжди видимий HUD тримає стриманий край. Здоров'я, мана та витривалість заливаються червоним, синім і оливковим. Cinzel обмежений заголовками та підзаголовками; основний текст лишає шрифт проєкту або типовий. Вбудований шрифт містить свою ліцензію в assets/fonts/cinzel/OFL.txt. Гравійований набір перемальовує bag, book, box, coin, crown, flag, heart, key, map, potion, shield, star, sword і user, а також додає scroll та seal. Кожне інше ім'я повертається до стандартного набору, тож close і settings зберігають свої типові малюнки в кожному пресеті. Cinzel покриває латиницю; для локалізованих заголовків дайте власний шрифт через shape.fonts. Що набір перевірок стежить в обох варіантах. Що вибрано середньовічний скін; що панелі меню та HUD — ковані рами, причому оздоба лише в меню; що заголовки беруть Cinzel, а основний текст лишає успадкований шрифт; що гравійовані іконки імпортуються як DPITexture; що справжній швидкий слот користується скіном; що зміна регуляторів у копії скіна доходить до слота, не чіпаючи пресету; і що перемикання назад відновлює стандартну та сай-фай геометрію.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # Або: GoUi.use_preset(GoThemePresets.MEDIEVAL_LIGHT)",-1],[4,"make-a-kingdom-of-your-own","Створіть власне королівство",1,"Теми в JSON можуть успадковувати інші теми в JSON. Пропущені значення зберігають налаштування батька; циклічне успадкування відхиляється. Згенерований пресет зберігає набір іконок свого батька. Параметр Дія shape.material 0: залізо · 1: шкіра · 2: пергамент. Керує позначками на поверхні. shape.grain_alpha Непрозорість текстури. Поставте 0 для чистої поверхні. shape.ornament_scale · shape.bevel_strength Розмір кутової оздоби меню та сила фаски-відблиску. shape.fonts Зіставляє ролі title, subtitle, caption, body і button із файлами шрифтів res://, що лежать у доповненні. Пропущені ролі лишають успадкований шрифт. skin.dials Радіус швидкого слота, видимість заклепок, зернистість і відблиск. Повна таблиця нижче перелічує кожен регулятор.","python3 addons/gohud/tools/new_theme.py kingdom --from medieval_dark # Відредагуйте themes/palettes/kingdom.json, а тоді: python3 addons/gohud/tools/make_theme.py kingdom godot --headless --path . --import # У GDScript, перед створенням віджетів: GoUi.use_preset(&\"kingdom\")",60],[4,"tokens","Токени",0,"Кожен колір і кожен розмір живуть під типом GoHud у темі й адресуються на ім'я. Правило таке: чисел не писати — імена йдуть услід, коли тему змінюють.","GoUi.color(GoTheme.ACCENT) # колір GoUi.metric(GoTheme.GAP) # розмір (dp) GoUi.font_size(GoTheme.ROLE_CAPTION) # розмір для текстової ролі GoUi.box(GoTheme.BOX_CARD) # копія StyleBox",-1],[4,"colours","Кольори",1,"Ім'я Для чого background Підлога екрана surface · surface_soft · surface_high Три шари панелей — панель, картка, піднята комірка border Рамки карток і кнопок text · secondary · muted Три рівні тексту — основний, допоміжний, приглушений accent · on_accent Акцент і текст, покладений на нього success · warning · danger · info Кольори статусів як текст *_fill Ті самі статуси як заливка — смуги та інші великі площини scrim · shadow · track Завіса за спливними вікнами, тіні, жолоб смуги Навіщо існує *_fill. Той самий зміст, протилежні вимоги. warning як текст мусить бути досить темним, щоб читатися на світлому тлі; як заливка смуги досвіду він мусить бути досить яскравим, щоб його помітили. Один токен не може бути обома — смуга у світлій темі ставала брунатною. Тема без варіанта _fill автоматично повертається до базового імені, тож теми, старші за ці токени, працюють далі.","",62],[4,"measurements-dp","Розміри (dp)",1,"touch button_height gap_tiny gap_small gap gap_large padding padding_compact compact_padding_x compact_padding_y radius_small radius radius_large screen_margin scroll_deadzone scroll_edge scrollbar_width list_glyph icon_size notice_duration_ms","",62],[4,"text-roles","Текстові ролі",1,"micro · compact · caption · body · button · subtitle · title — роль називає розмір, а не призначення. «Найбільший текст», а не «заголовок». Так шкала тримається навіть тоді, коли якийсь екран використовує її для чогось іншого.","",62],[4,"type-variations","Варіації типів",1,"GoPanel GoCard GoButton GoPrimaryButton GoDangerButton GoDangerSolidButton GoBareButton GoCompactButton GoIconButton GoListButton GoTitleLabel GoSubtitleLabel GoCaptionLabel GoCompactLabel GoMicroLabel","",62],[4,"skin","Скіни — там, куди темі не дістатися",0,"Метод Вирішує surface_box · floating_box · overlay_box Лицьові боки карток і панелей, плаваючі поверхні, «пігулки», покладені поверх гри чи карти chip_box · chip_ink Панель чипа й колір напису, який на ній лишається розбірливим slot_box · slot_ink Лицьові боки швидких слотів і їхній текст disc_box Коло за аватаром чи бейджем alert_box · skeleton_box · segment_box Вбудовані сповіщення, заглушки, сегментовані контроли coach_ring_box Позначка, якою навчальний тур обводить свою ціль draw_joystick · draw_coach_pointer Те, що малюється напряму — стик і його вказівник divider_color · divider_thickness · section_box Роздільники та заголовки секцій badge_box Бейджі швидких слотів — кількість і час, що лишився progress_fill_box · notice_box · tint_notice Заливки смуг (з обведенням там, де заливка не дотягує до 3:1 на своєму жолобі) та снекбари","class_name MySkin extends GoSkin func draw_joystick(canvas: CanvasItem, center: Vector2, knob: Vector2, radius: float, knob_radius: float, ink: Color, base: Color, active: bool) -> void: # Віджет уже обчислив позиції — тут відбувається лише малювання canvas.draw_circle(center, radius, Color(base, 0.4)) canvas.draw_circle(knob, knob_radius, ink)",-1],[4,"shapes-styleboxflat-cannot-make","Форми, яких StyleBoxFlat не вміє",1,"Клас Що малює GoStyleBoxCut Зрізані по діагоналі кути, один потовщений акцентний край, зовнішнє сяйво GoStyleBoxBracket Лише кутові позначки, лишаючи вміст необрамленим GoStyleBoxMedieval Кована рама — заклепки, кутове гравіювання, фаска-відблиск і зернистість заліза, шкіри чи пергаменту Усі три серіалізуються в ресурс Theme, як і будь-який інший StyleBox, — саме це й дозволяє темі міняти форму. Задавайте поля через content_margin_*. Якщо успадкувати StyleBox у GDScript, _get_style_margin() ніколи не викликається (виміряно на Godot 4.7). Заповнюйте вбудовані поля, інакше вміст притиснеться до рамки.","",67],[4,"own","Ваш власний пресет — один файл",0,"Раніше додати тему означало правити вручну чотири місця — палітру конструктора, форму, скін, ресурс пресету. Тепер одна команда ставить усе це на місце. Перший рядок пише themes/palettes/neon.json і themes/presets/neon.tres. Цей JSON несе кожне значення теми, від якої успадковується, повністю розписане, тож він заразом править за список того, що можна змінити: видаліть ключ, щоб зберегти батьківське значення, або впишіть його, щоб перевизначити. Пресети знаходяться скануванням теки themes/presets/, тож коду реєстру міняти не треба — випадний список у параметрах проєкту теж їх підхопить.","python3 addons/gohud/tools/new_theme.py neon --from scifi_dark --title \"Neon\" python3 addons/gohud/tools/make_theme.py neon # тема .tres + графіка контролів godot --headless --path . --import # один раз імпортувати нову графіку GoUi.use_preset(&\"neon\") # готово — вона з'явиться й у списку вибору",-1],[4,"what-you-can-change-on-one-page","Що можна змінити — на одній сторінці",1,"Де Що Як from батьківська тема dark · light · scifi_dark · medieval_dark · … або інша тема в JSON. Пропущені ключі успадковують її значення; цикл успадкування завершується помилкою palette тло · три поверхні · рамка · три відтінки тексту · акцент · чотири кольори статусів · завіса · тінь · жолоб смуги \"#RRGGBB\", альфа як \"#RRGGBB@0.35\" яскраві кольори лише для заливки *_vivid тримають смуги насиченими навіть тоді, коли колір тексту доводиться затемнити — пропустіть один, і конструктор про це скаже читабельність не налаштовується вручну. Текст, рамки, акцент і напис на ньому конструктор підіймає, доки вони не перевищать пороги — змініть лише акцент, і перевірки все одно пройдуть shape kind flat (заокруглені) · cut (зрізані кути) · medieval (ковані рами) розміри radius · radius_small · radius_large · gap · gap_small · gap_large · padding · button_height · button_padding[4] — токени йдуть услід, тож панелі й розрахунки віджетів ніколи не розходяться лише для cut cut_ratio · cut_max · corners (diagonal|all) · glow · edge лише для medieval material (0 залізо · 1 шкіра · 2 пергамент) · grain_alpha · ornament_scale · bevel_strength · fonts — title, subtitle, caption, body, button, зіставлені з файлами шрифтів res://, що лежать у доповненні skin base — родина для місць, які код малює сам (стик, слоти, бейджі, кільце коуч-мітки, чипи, роздільники) default · scifi · medieval dials — числа тих місць: ширина рамки слота й підфарбування, поля бейджа, непрозорість чипів і сповіщень, ширина та непрозорість кільця стика, розміри сай-фай фасок, сяйво й дужки Кожне батьківське значення розписане в JSON. Конструктор записує їх у themes/skins/gohud_skin_<id>.tres — коду скіна ніхто не чіпає. Лише щоб змінити самі малюнки, запускають --new-skin, який створює каркас підкласу GoSkin icons набір іконок шлях res:// до ресурсу GoIconSet — якщо пропустити, береться від батька в JSON dark · title як його показує список вибору булеве значення · рядок","",69],[4,"every-dial","Усі регулятори",1,"Таблицю нижче заповнює tools/make_site.py просто з рядків @export у скриптах скінів — додайте регулятор чи змініть типове значення, і таблиця піде услід. Уживайте ці імена під skin.dials у JSON. Регулятор, чиє типове значення читається як 14, — ціле число, а той, що читається як 10.0, — дробове; пишіть у JSON будь-яку форму, конструктор зведе її до типу зі скрипта. Стандартний скін GoSkin — 17 Регулятор Типове значення Що задає chip_fill_alpha 0.16 Непрозорість заливки панелі чипа. chip_edge_alpha 0.45 Непрозорість краю панелі чипа. alert_tint 0.1 Наскільки панель сповіщення підфарбовується в бік свого кольору статусу. slot_tint_lit 0.24 Акцентне підфарбування панелі швидкого слота, поки триває відкат. slot_tint_idle 0.08 Акцентне підфарбування панелі швидкого слота в спокої. slot_border_lit 2 Ширина рамки швидкого слота (dp), поки триває відкат. slot_border_idle 1 Ширина рамки швидкого слота (dp) у спокої. badge_pad_x 5 Горизонтальне внутрішнє поле (dp) бейджа (кількість, час, що лишився). badge_pad_y 1 Вертикальне внутрішнє поле (dp) бейджа. badge_edge_alpha 0.6 Непрозорість краю панелі бейджа. float_shadow_alpha 0.45 Непрозорість тіні плаваючих карток (коуч-мітка, картка-запит). float_shadow_size 14 Розмиття тіні (dp) плаваючих карток. float_shadow_lift 4 Зсув тіні плаваючої картки вниз (dp). float_glow_size 10.0 Відстань сяйва (dp) для плаваючої панелі, яка сяє замість того, щоб кидати тінь, як-от сай-фай панель зі зрізаними кутами. joystick_base_alpha 0.42 Непрозорість опорного диска стика. joystick_ring_alpha 0.45 Непрозорість кільця стика. joystick_ring_width 2.0 Ширина (dp) кільця стика. Сай-фай скін GoSkinSciFi — 10 Регулятор Типове значення Що задає cut_chip 7.0 Розмір фаски (dp) панелі чипа. cut_skeleton 5.0 Розмір фаски (dp) панелі-скелетона. cut_alert 8.0 Розмір фаски (dp) панелі сповіщення. cut_segment 8.0 Розмір фаски (dp) сегментованого контрола. cut_slot 6.0 Розмір фаски (dp) панелі швидкого слота. cut_disc_ratio 0.24 Фаска аватарів і дисків = діаметр × це співвідношення. slot_glow_alpha 0.45 Непрозорість сяйва слота, у якого триває відкат. slot_glow_size 6.0 Відстань сяйва (dp) слота, у якого триває відкат. bracket_arm 12.0 Довжина плеча (dp) прицільної дужки коуч-мітки. bracket_thickness 2.0 Товщина лінії (dp) прицільної дужки коуч-мітки. Середньовічний скін GoSkinMedieval — 5 Регулятор Типове значення Що задає slot_radius 4.0 Радіус кутів (dp) середньовічної рами швидкого слота. leather_grain_alpha 0.035 Непрозорість ледь помітних слідів шкіри всередині швидких слотів. ornament_scale 1.0 Масштаб металевих оздоб на кутах швидких слотів. Рами меню беруть shape.ornament_scale. bevel_strength 0.18 Сила металевого відблиску вздовж країв швидкого слота. slot_rivets 1 Показувати на швидких слотах маленькі металеві заклепки: 0 — ховає, 1 — показує.","",69],[4,"subclass-the-skin-optional","Успадкувати скін (необов'язково)",1,"У скіні живе лише те, куди не дістаються тема та форма — шестикутник стика, бейджі слотів, прицільна дужка коуч-мітки. Успадкуйте GoSkin, перевизначте саме ці методи й вкажіть у полі skin вашого JSON на цей ресурс. Тема, що міняє лише кольори, цей крок пропускає. Обіцянку стереже перевірка. tools/check_scaffold.sh щоразу створює одноразову тему — міняє акцент, ставить радіус у 4 — і перевіряє генерацію, поширення токенів і чистий прохід за контрастом, перш ніж її видалити. Перший же прогін виявив, що тема, у якій змінили лише акцент, провалює 8 пар: конструктор підіймав кольори тексту, але брав акцент таким, як написано. Тепер він підіймає й акцент, і напис на ньому.","",69],[4,"contrast","Читабельність вимірюють",0,"«Гарно» — справа смаку; «розбірливо» можна виміряти. Блідий сірий текст чудово виглядає на доброму моніторі й зникає на телефоні серед білого дня — вибір на око рано чи пізно це гарантує. Що Потрібно Основний текст 4,5 : 1 Великий текст (від 24px) 3 : 1 Акцентні рамки та іконки 3 : 1 Декоративні рамки 2 : 1 — WCAG не поширює своє правило 3:1 на декор Сусідні поверхні 1,12 : 1 — досить, щоб картка читалася окремо від свого тла","python3 addons/gohud/tools/check_contrast.py",-1],[4,"same-hue-text-on-a-same-hue-tint","Текст одного відтінку на підфарбуванні того самого відтінку",1,"Ця пастка траплялася в цій кодовій базі тричі — натиснуті кнопки (акцентна панель, акцентний напис), кнопки небезпеки та чипи. У зразку кольору вона має гарний вигляд і розсипається тієї ж миті, коли її виміряють, бо обидва кольори мають спільний відтінок і тому не різняться світлістю. Тому кольори написів не вибираються вручну. Конструктор тем і GoSkin кожен піднімає світлість — і лише світлість — доки поріг не буде перевищено на тій панелі, на якій текст справді лежить. Відтінок і насиченість виживають, тож палітра зберігає свій характер, а її зміна зберігає контраст.","",73],[4,"colour-read-as-text-and-colour-painted-as-area-w","Колір, який читають як текст, і колір, яким зафарбовують площину, хочуть протилежного",1,"У світлій темі колір попередження мусить потемніти, щоб лишитися читабельним як текст (#96500A). Коли заливка смуги успадковує його, смуга досвіду стає брунатною. Самим кольором цього не полагодити: жовтий яскравий за своєю природою, тож він перевищує 3:1 хіба що взагалі без сірого жолоба, а затемнення жолоба робить гірше (1,52 → 1,06). Тому їх розділено. Колір лишається насиченим — палітра несе кольори лише для заливки, як-от warning_vivid. Контраст несе край — GoSkin малює обведення в 1dp на будь-якій заливці, що не дотягує до 3:1 проти свого жолоба, тож «наскільки він повний» лишається розбірливим. Про пропуск вам повідомлять. Без *_vivid заливка, що вийшла темною, змушує конструктор надрукувати 막대가 칙칙하다 — 팔레트에 warning_vivid 를 더한다 (корейською: «смуга тьмяна — додайте до палітри warning_vivid»). Місце, яке раніше тихо псувалося, тепер про себе каже.","MY_LIGHT = dict( warning=hexc(\"9A5407\"), # читається як текст warning_vivid=hexc(\"F2A007\"), # зафарбовує смугу )",73],[4,"a-floating-panel-cannot-know-what-is-behind-it","Плаваюча панель не може знати, що за нею",1,"HUD малюється поверх гри — сніжного поля чи печери. Якщо його панель напівпрозора, те, що за нею, просочується крізь неї і змінює колір панелі, тягнучи за собою вниз і контраст тексту. При 82% непрозорості приглушений текст темних тем падав до 3,74:1 над яскравим тлом — нижче за мінімум. Тому напівпрозорі панелі вимірюють із чисто білим і чисто чорним позаду: це найгірше, що може запропонувати ігрова сцена. Панель HUD у вбудованих темах достатньо щільна, щоб пройти перевірку (92%), і водночас зберігає скляний вигляд. З тієї самої причини кольори іконок теж не закріплені. Гліф швидкого слота був жорстко заданий білим і виміряв 1,11:1 у світлій темі — тепер він іде за панеллю, на якій сидить, точно так само, як і написи. Два перевіряльники, два засяги. check_contrast.py читає файли тем; кольори, які скін змішує під час роботи (чипи, слоти), вимірює розділ skin contrast набору перевірок усередині Godot.","",73]]};
